```
#include<unistd.h>
#include<fcntl.h>
#include<sys/stat.h>
#include<sys/mman.h>
#include<stdio.h>
#include<string.h>
#include<iostream>
usingnamespacestd;
intmain(intargc,char*argv[]){
if(argc!=3){
cerr<<"Usage:"<<argv[0]<<"infileoutfile"<<endl;
return-1;
}
intfd_in=open(argv[1],O_RDONLY);
if(fd_in<0){
perror(argv[1]);
return-1;
}
structstatinfo;
if(fstat(fd_in,&info)<0){
perror("Errorstatinginputfile");
return-1;
}
void*addr_in=
mmap(0,info.st_size,PROT_READ,MAP_SHARED,fd_in,0);
if(addr_in==MAP_FAILED){
perror("Errormappinginputfile");
return-1;
}
```

